import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

instance_norm_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void instance_norm_kernel(const float* input, float* output, int B, int C, int H, int W, float eps) {
    int bc_id = blockIdx.x;
    int b = bc_id / C;
    int c = bc_id % C;

    int tid = threadIdx.x;
    int elements_per_bc = H * W;
    int elements_per_thread = (elements_per_bc + blockDim.x - 1) / blockDim.x;

    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (int i = 0; i < elements_per_thread; ++i) {
        int idx = tid + i * blockDim.x;
        if (idx < elements_per_bc) {
            int input_idx = (b * C + c) * H * W + idx;
            float val = input[input_idx];
            sum += val;
            sum_sq += val * val;
        }
    }

    __shared__ float s_sum[256];
    __shared__ float s_sum_sq[256];
    s_sum[tid] = sum;
    s_sum_sq[tid] = sum_sq;
    __syncthreads();

    for (int s = blockDim.x/2; s > 0; s >>= 1) {
        if (tid < s) {
            s_sum[tid] += s_sum[tid + s];
            s_sum_sq[tid] += s_sum_sq[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float total_sum = s_sum[0];
        float total_sum_sq = s_sum_sq[0];
        float mean = total_sum / elements_per_bc;
        float var = (total_sum_sq / elements_per_bc) - (mean * mean);
        float inv_std = rsqrtf(var + eps);

        __shared__ float s_mean, s_inv_std;
        s_mean = mean;
        s_inv_std = inv_std;
        __syncthreads();
    } else {
        __syncthreads();
    }

    float mean = s_mean;
    float inv_std = s_inv_std;

    for (int i = 0; i < elements_per_thread; ++i) {
        int idx = tid + i * blockDim.x;
        if (idx < elements_per_bc) {
            int input_idx = (b * C + c) * H * W + idx;
            float val = input[input_idx];
            output[input_idx] = (val - mean) * inv_std;
        }
    }
}

torch::Tensor instance_norm_cuda(torch::Tensor input, float eps) {
    int B = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    auto output = torch::empty_like(input);
    int total_bc = B * C;
    int threads = 256;

    const float* input_data = input.data_ptr<float>();
    float* output_data = output.data_ptr<float>();

    instance_norm_kernel<<<total_bc, threads>>>(input_data, output_data, B, C, H, W, eps);

    return output;
}
"""

instance_norm_cpp_source = "torch::Tensor instance_norm_cuda(torch::Tensor input, float eps);"

instance_norm = load_inline(
    name='instance_norm',
    cpp_sources=instance_norm_cpp_source,
    cuda_sources=instance_norm_source,
    functions=['instance_norm_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, num_features: int):
        super(ModelNew, self).__init__()
        self.eps = 1e-5

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        return instance_norm.instance_norm_cuda(x, self.eps)
